INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24001, 24, 0, "2020/04/30 12:00:00", 0, 0, 0, 1, "あたしだって\nやるときはやるよ！", 1, "リン", "2030/12/17 14:59:59");
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24002, 24, 0, "2020/04/30 12:00:00", 0, 0, 1, 1, "ふぅ…\nこれであたしの仕事は\n終わりだね", 1, "リン", "2030/12/17 14:59:59");
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24003, 24, 0, "2020/04/30 12:00:00", 0, 0, 2, 1, "終わった終わった\n一人でもなんとか\nなるもんだね", 1, "リン", "2030/12/17 14:59:59");
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24004, 24, 0, "2020/04/30 12:00:00", 0, 0, 3, 2, "やったね！\nこれでようやく\nサボれるよ…", 2, "リン", "2030/12/17 14:59:59");
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24005, 24, 0, "2020/04/30 12:00:00", 0, 0, 4, 1, "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 1, "リン", "2030/12/17 14:59:59");
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24006, 24, 0, "2020/04/30 12:00:00", 0, 0, 5, 2, "あたしを敵に回した\n恐ろしさ\n思い知ったか！", 2, "リン", "2030/12/17 14:59:59");
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24007, 24, 0, "2020/04/30 12:00:00", 0, 0, 6, 2, "あたしも意外と\nやるもんでしょ？", 2, "リン", "2030/12/17 14:59:59");
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24008, 24, 0, "2020/04/30 12:00:00", 0, 0, 7, 4, "疲れた…\nねずみの逃げ足\n速すぎるよ…", 4, "リン", "2030/12/17 14:59:59");
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24009, 24, 0, "2020/04/30 12:00:00", 0, 0, 8, 4, "このままじゃ\nまっひ～に\n叱られちゃうよ", 4, "リン", "2030/12/17 14:59:59");
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24010, 24, 0, "2020/04/30 12:00:00", 0, 0, 9, 4, "まじめに\nやったんだけどな…\n悔しいな～", 4, "リン", "2030/12/17 14:59:59");
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24011, 24, 0, "2020/04/30 12:00:00", 0, 0, 10, 4, "やられた…\nねずみって意外と\nてごわいね", 4, "リン", "2030/12/17 14:59:59");
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24012, 24, 0, "2020/04/30 12:00:00", 0, 0, 11, 4, "おのれ～\nあたしのチーズを\n盗みやがって～！", 4, "リン", "2030/12/17 14:59:59");
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, 10040, 24013, 24, 1.81, "2020/04/30 12:00:00", 0, 0, 12, 1, "疲れた…\nけど、次こそは\n守り抜くよ…", 4, "リン", "2030/12/17 14:59:59");
